(5700219, 829507, 51793, '<td valign="top">I don''t understand how you can have a centered comp and a rule of 3rds at the same time.</td>', 'I don''t understand how you can have a centered comp and a rule of 3rds at the same time.', '2009-10-26 00:09:47.000000', NULL, 1),
(5700221, 829157, 72103, '<td valign="top">GReat image, but I''m sure I won''t be alone in saying ......   Ahmm, what about the title?  Still, a 7 from me....  :)</td>', 'GReat image, but I''m sure I won''t be alone in saying ......   Ahmm, what about the title?  Still, a 7 from me....  :)', '2009-10-26 00:10:17.000000', NULL, 1),
(5700229, 829448, 86090, '<td valign="top">What a lovely portrait. Great work.</td>', 'What a lovely portrait. Great work.', '2009-10-26 00:12:20.000000', NULL, 1),
(5700231, 829211, 77521, '<td valign="top">nice portrait, although the blown out left shoulder is very distracting</td>', 'nice portrait, although the blown out left shoulder is very distracting', '2009-10-26 00:12:47.000000', NULL, 1),
(5700236, 829342, 86090, '<td valign="top">Excellent capture!</td>', 'Excellent capture!', '2009-10-26 00:13:32.000000', NULL, 1),
(5700241, 829322, 77521, '<td valign="top">beautiful portrait!!!! 10</td>', 'beautiful portrait!!!! 10', '2009-10-26 00:14:08.000000', NULL, 1),
(5700242, 829157, 65562, '<td valign="top">DNMC- list techniques in title</td>', 'DNMC- list techniques in title', '2009-10-26 00:14:55.000000', NULL, 1),
(5700243, 829542, 15711, '<td valign="top">That hand in the foreground is really a distraction, but I''m one of those weirdos that doesn''t care for foreground blur. LOL</td>', 'That hand in the foreground is really a distraction, but I''m one of those weirdos that doesn''t care for foreground blur. LOL', '2009-10-26 00:16:29.000000', NULL, 1),
(5700253, 829526, 15711, '<td valign="top">GOD THAT IS FANTASTIC!!!  The catch lights and the subtle lighting to the left.  This is awesome. Love your use of negative space and the crop.  That bit of "red" under the right eye might be my monitor so I''m not going to take off for it.  Wow - this is great.</td>', 'GOD THAT IS FANTASTIC!!!  The catch lights and the subtle lighting to the left.  This is awesome. Love your use of negative space and the crop.  That bit of "red" under the right eye might be my monitor so I''m not going to take off for it.  Wow - this is great.', '2009-10-26 00:18:46.000000', NULL, 1),
(5700256, 829516, 15711, '<td valign="top">Excellent!!!!  I love everything about it.</td>', 'Excellent!!!!  I love everything about it.', '2009-10-26 00:19:19.000000', NULL, 1),
(5700258, 829138, 15711, '<td valign="top">Well, I couldn''t have asked for a photo I could love any more.  What a little love!!!!!</td>', 'Well, I couldn''t have asked for a photo I could love any more.  What a little love!!!!!', '2009-10-26 00:20:26.000000', NULL, 1),
(5700261, 829144, 15711, '<td valign="top">Uh oh!!  Where is the description of your three techniques??</td>', 'Uh oh!!  Where is the description of your three techniques??', '2009-10-26 00:21:19.000000', NULL, 1),
(5700266, 829183, 15711, '<td valign="top">That''s four. LOL  Really nice portrait. I do find the background really distracting though.</td>', 'That''s four. LOL  Really nice portrait. I do find the background really distracting though.', '2009-10-26 00:22:09.000000', NULL, 1),
(5700274, 829178, 15711, '<td valign="top">Oh my!! This is beautiful. Wouldn''t the moon be less centered if it were true rule of thirds?  No points taken off, just wondering.</td>', 'Oh my!! This is beautiful. Wouldn''t the moon be less centered if it were true rule of thirds?  No points taken off, just wondering.', '2009-10-26 00:23:27.000000', NULL, 1),
(5700279, 829599, 15711, '<td valign="top">Really pretty but I think the bottom leaf needs to be tack sharp. :~)</td>', 'Really pretty but I think the bottom leaf needs to be tack sharp. :~)', '2009-10-26 00:24:04.000000', NULL, 1),
(5700282, 829421, 15711, '<td valign="top">I love this.  So simple.</td>', 'I love this.  So simple.', '2009-10-26 00:24:28.000000', NULL, 1),
(5700284, 829541, 15711, '<td valign="top">Almost rule of thirds too.  Really soft and simple. :~)</td>', 'Almost rule of thirds too.  Really soft and simple. :~)', '2009-10-26 00:25:03.000000', NULL, 1),
(5700286, 829214, 15711, '<td valign="top">Not crazy about the vivid border stripe. Rule of thirds? Hmmmmm Still really pretty. I love fall leaves.</td>', 'Not crazy about the vivid border stripe. Rule of thirds? Hmmmmm Still really pretty. I love fall leaves.', '2009-10-26 00:26:07.000000', NULL, 1),
(5700288, 829211, 15711, '<td valign="top">I love her expression.  Almost like one of the Victorian ones, where no one smiled. Great focus on her eyes. I like how the left part of her shirt disappears into the white background.</td>', 'I love her expression.  Almost like one of the Victorian ones, where no one smiled. Great focus on her eyes. I like how the left part of her shirt disappears into the white background.', '2009-10-26 00:26:53.000000', NULL, 1),
(5700289, 828907, 27161, '<td valign="top">nice composition.  I would have cropped it a little differently, if possible, to center the memorial or to apply it to the rule of thirds technique.</td>', 'nice composition.  I would have cropped it a little differently, if possible, to center the memorial or to apply it to the rule of thirds technique.', '2009-10-26 00:26:59.000000', NULL, 1),
(5700292, 829470, 15711, '<td valign="top">This would be so cool if we could see it about triple the size.  Nice use of simple line and light. I might have not cropped it quite so tight at the top. 7</td>', 'This would be so cool if we could see it about triple the size.  Nice use of simple line and light. I might have not cropped it quite so tight at the top. 7', '2009-10-26 00:27:51.000000', NULL, 1),
(5700294, 828795, 27161, '<td valign="top">Hilarious shot</td>', 'Hilarious shot', '2009-10-26 00:28:07.000000', NULL, 1),
(5700296, 829295, 15711, '<td valign="top">NICE!!!  Love the flare of the sun. Great silhouette and long shadow.</td>', 'NICE!!!  Love the flare of the sun. Great silhouette and long shadow.', '2009-10-26 00:28:39.000000', NULL, 1),
(5700298, 829598, 15711, '<td valign="top">Oh my!  Her feathered cowl/hood almost looks like a painting.  Really nice.</td>', 'Oh my!  Her feathered cowl/hood almost looks like a painting.  Really nice.', '2009-10-26 00:29:21.000000', NULL, 1),
(5700300, 828789, 15711, '<td valign="top">Terrific focus. Love the lines.</td>', 'Terrific focus. Love the lines.', '2009-10-26 00:29:42.000000', NULL, 1),
(5700302, 829150, 15711, '<td valign="top">HEE HEE - that lavender in the background is terrific.</td>', 'HEE HEE - that lavender in the background is terrific.', '2009-10-26 00:30:09.000000', NULL, 1),
(5700304, 829545, 15711, '<td valign="top">Stunning.  The colors and focus - spot on.</td>', 'Stunning.  The colors and focus - spot on.', '2009-10-26 00:30:21.000000', NULL, 1),
(5700305, 829496, 27161, '<td valign="top">Poor noseless cat.  Well lit, and great expression of mood.</td>', 'Poor noseless cat.  Well lit, and great expression of mood.', '2009-10-26 00:30:36.000000', NULL, 1),
(5700307, 829088, 15711, '<td valign="top">NICE!!!  Fabulous focus and colors.</td>', 'NICE!!!  Fabulous focus and colors.', '2009-10-26 00:31:31.000000', NULL, 1),
(5700308, 829558, 15711, '<td valign="top">That''s wild and quite wonderful!! 10</td>', 'That''s wild and quite wonderful!! 10', '2009-10-26 00:32:04.000000', NULL, 1),
