(5700313, 829464, 111032, '<td valign="top">would have like it better without the bird in the foreground. still a great shot and well processed</td>', 'would have like it better without the bird in the foreground. still a great shot and well processed', '2009-10-26 00:33:10.000000', NULL, 1),
(5700316, 829495, 15711, '<td valign="top">This is my kind of shot.  Love the colors. Rich and deep. YES!!</td>', 'This is my kind of shot.  Love the colors. Rich and deep. YES!!', '2009-10-26 00:33:50.000000', NULL, 1),
