(5700326, 828685, 15711, '<td valign="top">Reminds me of Buster Keeton with a little Pablo Picasso thrown in.  This is great.</td>', 'Reminds me of Buster Keeton with a little Pablo Picasso thrown in.  This is great.', '2009-10-26 00:36:45.000000', NULL, 1),
(5700339, 828894, 27161, '<td valign="top">Definitely my favorite.</td>', 'Definitely my favorite.', '2009-10-26 00:43:59.000000', NULL, 1),
(5700340, 829595, 52336, '<td valign="top">I think this would have worked much better without vignette.  There''s also purple fringing that really detracts.  Otherwise, this is a good portrait.  6</td>', 'I think this would have worked much better without vignette.  There''s also purple fringing that really detracts.  Otherwise, this is a good portrait.  6', '2009-10-26 00:45:21.000000', NULL, 1),
