(5701979, 829524, 32767, '<td valign="top">One of the better images in the Challenge, imo. The techniques were used together well to great effect. The missing arm (if there''s an arm there?) is maybe a little odd to the eye but overall, I like the shot.</td>', 'One of the better images in the Challenge, imo. The techniques were used together well to great effect. The missing arm (if there''s an arm there?) is maybe a little odd to the eye but overall, I like the shot.', '2009-10-27 10:41:40.000000', NULL, 1),
(5701985, 828685, 98339, '<td valign="top">could have even added Portrait with this.  excellent choice...really like this in B&amp;W</td>', 'could have even added Portrait with this.  excellent choice...really like this in B&W', '2009-10-27 10:43:47.000000', NULL, 1),
(5701987, 829617, 98339, '<td valign="top">are you sure this is "low key"...I thought "low key" was dark in the composition...and "high key" would be light and bright like this...that given...I do like the picture (lol) well done</td>', 'are you sure this is "low key"...I thought "low key" was dark in the composition...and "high key" would be light and bright like this...that given...I do like the picture (lol) well done', '2009-10-27 10:44:59.000000', NULL, 1),
