INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5702024, 829465, 98339, '<td valign="top">very pleasing shot...your execution of elements is well done</td>', 'very pleasing shot...your execution of elements is well done', '2009-10-27 11:17:01.000000', NULL, 1),
(5702028, 829613, 56828, '<td valign="top">I think your intent was to have the puddle at the bottom be your main subject.  But the lighting and lines lead me directly to the "waterfall" which is directly in the center of the photo rather than at a third.  I also think you have too much light (in my opinion) to be low key.  The photo itself is very serene and I like it''s simplicity.</td>', 'I think your intent was to have the puddle at the bottom be your main subject.  But the lighting and lines lead me directly to the "waterfall" which is directly in the center of the photo rather than at a third.  I also think you have too much light (in my opinion) to be low key.  The photo itself is very serene and I like it''s simplicity.', '2009-10-27 11:22:26.000000', NULL, 1),
(5702040, 829012, 98339, '<td valign="top">it does look the the bird is just hanging there...good composition</td>', 'it does look the the bird is just hanging there...good composition', '2009-10-27 11:33:18.000000', NULL, 1),
(5702041, 829341, 98339, '<td valign="top">I like all your elements, but the colors in the PP are a little to blue for me...(just my opinion)</td>', 'I like all your elements, but the colors in the PP are a little to blue for me...(just my opinion)', '2009-10-27 11:34:04.000000', NULL, 1),
