(5704096, 829212, 83313, '<td valign="top">Cool catch. My nitpick (and it is truly a nitpick) is the buildings lean in slightly. A touch of perspective correction is needed there. You could have probably cloned out the streetlamp under advanced rules.</td>', 'Cool catch. My nitpick (and it is truly a nitpick) is the buildings lean in slightly. A touch of perspective correction is needed there. You could have probably cloned out the streetlamp under advanced rules.', '2009-10-28 13:24:36.000000', NULL, 1),
(5704099, 829526, 83313, '<td valign="top">The blurred background looks like shallow depth of field to me. Calling it rule of thirds instead would have worked for me, as that is where his eyes are. Other than that, this is a great portrait. I hope to eventually get this good with lighting.</td>', 'The blurred background looks like shallow depth of field to me. Calling it rule of thirds instead would have worked for me, as that is where his eyes are. Other than that, this is a great portrait. I hope to eventually get this good with lighting.', '2009-10-28 13:28:37.000000', NULL, 1),
