INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5706090, 829157, 99710, '<td valign="top">well, you didn''t read the rules with regards to the title of the photo.</td>', 'well, you didn''t read the rules with regards to the title of the photo.', '2009-10-29 22:50:33.000000', NULL, 1),
(5706091, 829231, 99710, '<td valign="top">nice work!</td>', 'nice work!', '2009-10-29 22:50:41.000000', NULL, 1),
(5706092, 829610, 99710, '<td valign="top">love his expression. nice job.</td>', 'love his expression. nice job.', '2009-10-29 22:51:02.000000', NULL, 1),
(5706094, 828468, 99710, '<td valign="top">love the feel of this photo, excellent use of the 3 techniques. It''s sad that I can''t vote otherwise I''ll give this one a 10. (Well now I can vote, now your 10)</td>', 'love the feel of this photo, excellent use of the 3 techniques. It''s sad that I can''t vote otherwise I''ll give this one a 10. (Well now I can vote, now your 10)', '2009-10-29 22:52:19.000000', NULL, 1),
(5706105, 829580, 50695, '<td valign="top">shallow dof???????</td>', 'shallow dof???????', '2009-10-29 23:18:10.000000', NULL, 1),
(5706108, 829226, 83313, '<td valign="top">Strikes me a little more as rule of thirds, rather than centered comp. Although the nose is dead center, the skull itself is slightly off center and my eye is led to the eye sockets which are in the ROT zone. Just shows that such compositional concepts are very much open to interpretation and are sometimes hard to actually nail down. What really matters is whether what you do with it works or doesn''t.<br/> <br/>Nice details and good strong b/w tones. Just in time for Halloween.</td>', 'Strikes me a little more as rule of thirds, rather than centered comp. Although the nose is dead center, the skull itself is slightly off center and my eye is led to the eye sockets which are in the ROT zone. Just shows that such compositional concepts are very much open to interpretation and are sometimes hard to actually nail down. What really matters is whether what you do with it works or doesn''t. Nice details and good strong b/w tones. Just in time for Halloween.', '2009-10-29 23:20:09.000000', NULL, 1),
(5706110, 829507, 83313, '<td valign="top">Reminds me of the slo-mo bullet dodging scene from "The Matrix".</td>', 'Reminds me of the slo-mo bullet dodging scene from "The Matrix".', '2009-10-29 23:21:18.000000', NULL, 1),
(5706112, 829466, 83313, '<td valign="top">Comes across quite a bit grainy on my monitor. Looks like high ISO noise.</td>', 'Comes across quite a bit grainy on my monitor. Looks like high ISO noise.', '2009-10-29 23:22:45.000000', NULL, 1),
(5706114, 829578, 83313, '<td valign="top">Nice use of the ROT. Instead of just plopping a subject on a set of crosshairs, you are using the idea to lead the eye where you want it to go. Excellent example.</td>', 'Nice use of the ROT. Instead of just plopping a subject on a set of crosshairs, you are using the idea to lead the eye where you want it to go. Excellent example.', '2009-10-29 23:24:18.000000', NULL, 1),
(5706115, 829525, 83313, '<td valign="top">Looks almost like a painting. Sweet.</td>', 'Looks almost like a painting. Sweet.', '2009-10-29 23:25:03.000000', NULL, 1),
(5706116, 829617, 83313, '<td valign="top">A very sharp sharpie. Clean shot with no noise. Nicely done.</td>', 'A very sharp sharpie. Clean shot with no noise. Nicely done.', '2009-10-29 23:26:18.000000', NULL, 1),
(5706118, 829498, 83313, '<td valign="top">Oh, big eyes. I''m a sucker for big eyes.</td>', 'Oh, big eyes. I''m a sucker for big eyes.', '2009-10-29 23:26:52.000000', NULL, 1),
(5706120, 829144, 83313, '<td valign="top">Rule of thirds, long exposure, and I''m not sure about the third one. Could be several. I''m sure you are already getting slapped with DNMC''s for forgetting to list your 3 techniques. I won''t add to it.</td>', 'Rule of thirds, long exposure, and I''m not sure about the third one. Could be several. I''m sure you are already getting slapped with DNMC''s for forgetting to list your 3 techniques. I won''t add to it.', '2009-10-29 23:29:46.000000', NULL, 1),
(5706156, 828651, 83313, '<td valign="top">Very dramatic looking. I like it a lot.</td>', 'Very dramatic looking. I like it a lot.', '2009-10-30 00:36:28.000000', NULL, 1),
(5706157, 829604, 83313, '<td valign="top">Something got seriously messed up here, resulting in a very blocky or oversharpened appearance. My guess is your resizing method  was not the right one for retaining detail in this scene. If not for that major problem, I would be giving this a nice high vote. As it is, I feel I can only give it a 4, for a good effort that has a major issue.</td>', 'Something got seriously messed up here, resulting in a very blocky or oversharpened appearance. My guess is your resizing method  was not the right one for retaining detail in this scene. If not for that major problem, I would be giving this a nice high vote. As it is, I feel I can only give it a 4, for a good effort that has a major issue.', '2009-10-30 00:40:53.000000', NULL, 1),
(5706158, 828907, 83313, '<td valign="top">You have lots of JPEG compression taking away detail and leaving blocky artifacts in areas. The 47k file size supports this. Compression kills detail. Always use the least amount of compression you can get away with and still come in under the challenge limit.<br/> <br/>I''ll leave it to the others to slap you with DNMC''s over the missing techniques in the title. That''s a mere technicality, but the compression is a real problem that you can fix.</td>', 'You have lots of JPEG compression taking away detail and leaving blocky artifacts in areas. The 47k file size supports this. Compression kills detail. Always use the least amount of compression you can get away with and still come in under the challenge limit. I''ll leave it to the others to slap you with DNMC''s over the missing techniques in the title. That''s a mere technicality, but the compression is a real problem that you can fix.', '2009-10-30 00:45:57.000000', NULL, 1),
(5706208, 829183, 18655, '<td valign="top">The use of Neat Image or the like may look a little overdone but gives an ok effect nevertheless. I always like to apply it to such a degree that it does make a difference but without anyone knowing for sure that I used it.<br/>I would also maybe not have sharpened the shirt as much as the rest of the image to avoid the shirt stealing focus from the main subject but this is just nitpicky stuff. He is after all not a teenager so a bit more weathered look would have been appropriate.<br/>I love the detail with the arm/hand including the watch. The fact that he is wearing an ''old school'' watch (that he probably owned since before marriage)does in my opinion tell me a lot of the man. No doubt down to earth, sensible and not at all materialistic. The one nail that is showing is 100% clean (this makes me happy!) and clipped in a way that tells me he pays attention to detail. Is he an avid golfer?<br/>The lighting is very good and I do like the hard''ish contrast but I do see some vignetting that I definitely would have removed. You may have left it there on purpose or even added it in post edit, but I still do not think it looks good here due to the backlight which to me makes it look a little dirty.<br/>I love the overall look of the image, the pose, expression, choice of b/w, bokeh and crop. Well done - 8.<br/>A little less neat image/increased texture in his face and and a little softer focus on the shirt would have given you a better score from me though.</td>', 'The use of Neat Image or the like may look a little overdone but gives an ok effect nevertheless. I always like to apply it to such a degree that it does make a difference but without anyone knowing for sure that I used it.I would also maybe not have sharpened the shirt as much as the rest of the image to avoid the shirt stealing focus from the main subject but this is just nitpicky stuff. He is after all not a teenager so a bit more weathered look would have been appropriate.I love the detail with the arm/hand including the watch. The fact that he is wearing an ''old school'' watch (that he probably owned since before marriage)does in my opinion tell me a lot of the man. No doubt down to earth, sensible and not at all materialistic. The one nail that is showing is 100% clean (this makes me happy!) and clipped in a way that tells me he pays attention to detail. Is he an avid golfer?The lighting is very good and I do like the hard''ish contrast but I do see some vignetting that I definitely would have removed. You may have left it there on purpose or even added it in post edit, but I still do not think it looks good here due to the backlight which to me makes it look a little dirty.I love the overall look of the image, the pose, expression, choice of b/w, bokeh and crop. Well done - 8.A little less neat image/increased texture in his face and and a little softer focus on the shirt would have given you a better score from me though.', '2009-10-30 04:02:00.000000', NULL, 1),
(5706209, 829214, 18655, '<td valign="top">Nicely composed. Lighting is perfect. 7</td>', 'Nicely composed. Lighting is perfect. 7', '2009-10-30 04:03:26.000000', NULL, 1),
(5706212, 828651, 18655, '<td valign="top">Very well done! The post processing is very appropriate and the angle is picked to perfection. It would not have hurt to not have the background in focus but this is very nitpicky. 7</td>', 'Very well done! The post processing is very appropriate and the angle is picked to perfection. It would not have hurt to not have the background in focus but this is very nitpicky. 7', '2009-10-30 04:05:46.000000', NULL, 1),
(5706214, 829598, 18655, '<td valign="top">Excellent portrait with good lighting. Good choice to only leave her face in focus. Otherwise the fur would have stolen to much from the main subject and it would have been an entirely different image.<br/>I could have done without the shade on her left (viewer''s right) cheeck and I guess if you had worked a little on her hair and/or fur you could have avoided it. Then again; it does aid to accentuate her cheek bone... <br/>8 points</td>', 'Excellent portrait with good lighting. Good choice to only leave her face in focus. Otherwise the fur would have stolen to much from the main subject and it would have been an entirely different image.I could have done without the shade on her left (viewer''s right) cheeck and I guess if you had worked a little on her hair and/or fur you could have avoided it. Then again; it does aid to accentuate her cheek bone... 8 points', '2009-10-30 04:12:23.000000', NULL, 1),
(5706217, 828992, 18655, '<td valign="top">Did you use a tilt/shift lense, full format camera or did you add the focus line in post edit? Either way it gives the image an interesting look.<br/>Well done - 7</td>', 'Did you use a tilt/shift lense, full format camera or did you add the focus line in post edit? Either way it gives the image an interesting look.Well done - 7', '2009-10-30 04:14:05.000000', NULL, 1),
(5706221, 829488, 18655, '<td valign="top">Very well done but a little messy. To me it''s a little hard to see what''s going on with the umbrella and there is something that just doesn''t jive... maybe that it looks like an action shot with a strong gust damaging her umbrella but at the same time her hands and face shows more evidence of a relaxed stroll in the sun. But I do like the concept and the overall look of the image.</td>', 'Very well done but a little messy. To me it''s a little hard to see what''s going on with the umbrella and there is something that just doesn''t jive... maybe that it looks like an action shot with a strong gust damaging her umbrella but at the same time her hands and face shows more evidence of a relaxed stroll in the sun. But I do like the concept and the overall look of the image.', '2009-10-30 04:21:16.000000', NULL, 1),
(5706225, 829507, 18655, '<td valign="top">Very cool. Gives a bit of a stock photo feeling but could easily at the same time have been a fashion shot. This is just a guess but it looks as though you might have had an all burned out background that you slightly altered to take away from the stock photo look.<br/>Lighting is no doubt done to perfection (great job accentuating her cheek bones!) and the pose is awesome (how?!?). The wide angle choice from above is unusual and fun.<br/>The image has a lot of depth - almost 3D like. And when details are this small it is the more important to have this depth. For example separating the chin from the neck which is perfect here.<br/>Maybe not an image articulating the deepest message but for what you were trying to accomplish there is IMO nothing to deduct - 10 points.</td>', 'Very cool. Gives a bit of a stock photo feeling but could easily at the same time have been a fashion shot. This is just a guess but it looks as though you might have had an all burned out background that you slightly altered to take away from the stock photo look.Lighting is no doubt done to perfection (great job accentuating her cheek bones!) and the pose is awesome (how?!?). The wide angle choice from above is unusual and fun.The image has a lot of depth - almost 3D like. And when details are this small it is the more important to have this depth. For example separating the chin from the neck which is perfect here.Maybe not an image articulating the deepest message but for what you were trying to accomplish there is IMO nothing to deduct - 10 points.', '2009-10-30 04:35:26.000000', NULL, 1),
(5706226, 829592, 18655, '<td valign="top">Lovely abstract. Good choice of colors. 7 points</td>', 'Lovely abstract. Good choice of colors. 7 points', '2009-10-30 04:36:37.000000', NULL, 1),
(5706229, 829559, 18655, '<td valign="top">Lovely warm fall tones. Gives me a calm feeling and very pleasing to look at. 7</td>', 'Lovely warm fall tones. Gives me a calm feeling and very pleasing to look at. 7', '2009-10-30 04:39:41.000000', NULL, 1),
(5706231, 829458, 18655, '<td valign="top">Very nice. Love the composition and choice of post edit - 8</td>', 'Very nice. Love the composition and choice of post edit - 8', '2009-10-30 04:40:33.000000', NULL, 1),
(5706232, 829607, 18655, '<td valign="top">Fun shot with great colors and lots of life - 7</td>', 'Fun shot with great colors and lots of life - 7', '2009-10-30 04:41:27.000000', NULL, 1),
(5706234, 828407, 18655, '<td valign="top">Great shot! Crop, sharpness, lighting is all good. It''s also fun and interesting and I love the variety of colors. 9</td>', 'Great shot! Crop, sharpness, lighting is all good. It''s also fun and interesting and I love the variety of colors. 9', '2009-10-30 04:46:58.000000', NULL, 1),
